package dev.investai.portfolio.domain;

import java.util.UUID;

/**
 * Identifier of a {@link PortfolioLine}, generated by the application.
 *
 * @param value the UUID
 */
public record PortfolioLineId(UUID value) {

  /**
   * Generates a new identifier.
   *
   * @return a random identifier
   */
  public static PortfolioLineId newId() {
    return new PortfolioLineId(UUID.randomUUID());
  }

  @Override
  public String toString() {
    return value.toString();
  }
}
